const {test}=require('node:test'),assert=require('node:assert/strict');
const G=require('../dist/agency-plans/geometry'),R=require('../dist/agency-plans/raster'),C=require('../dist/agency-plans/commercial'),P=require('../dist/agency-plans/pipeline');
const Records=require('../dist/agency-plans/records');
const Provider=require('../dist/agency-plans/provider');
const rect=(x,y,w,h)=>({points:[[x,y],[x+w,y],[x+w,y+h],[x,y+h]],holes:[]});
const calibration={start:[0,0],end:[10,0],metres:10,confirmed:true,maxRelativeError:.01};
const base=()=>({calibration,geometryRevision:1,policyVersion:'agency-user-v1',surfaces:[{id:'main',kind:'principal',geometry:rect(0,0,10,8)}],walls:[],coverageConfirmed:true,wallCoverageConfirmed:true,policyConfirmed:true,unresolvedSymbols:[],commonWallCapBasis:'physical_thickness'});
const config={version:'synthetic-v1',threshold:180,closingRadius:0,minRegionPixels:4,maxRegionFraction:.8,simplifyPixels:0,fillTextHolesUpToPixels:0};
function raster(){const gray=new Uint8Array(80*60).fill(255);const black=(x,y)=>gray[y*80+x]=0;for(const [x,y,w,h] of [[5,5,25,35],[35,5,35,35]]){for(let i=x;i<=x+w;i++){black(i,y);black(i,y+h);}for(let j=y;j<=y+h;j++){black(x,j);black(x+w,j);}}return {width:80,height:60,gray};}
const spaces=()=>[{id:'a',kind:'room',label:'Room A',seeds:[[15,15]]},{id:'b',kind:'corridor',label:'Room B',seeds:[[45,15]]}];
test('rectangle area subtracts pillar hole',()=>{const p=rect(0,0,10,8);p.holes=[rect(3,3,1,1).points];assert.equal(G.validPolygon(p),true);assert.equal(G.polygonArea(p),79);});
test('bowtie, duplicate points and touching hole are rejected',()=>{assert.equal(G.validPolygon({points:[[0,0],[3,3],[0,3],[3,0]],holes:[]}),false);const p=rect(0,0,4,4);p.points.push([0,0]);assert.equal(G.validPolygon(p),false);assert.equal(G.validPolygon({...rect(0,0,4,4),holes:[rect(0,1,1,1).points]}),false);});
test('identical and coincident-edge overlaps detected, adjacent rooms allowed',()=>{assert.equal(G.overlaps(rect(0,0,4,4),rect(0,0,4,4)),true);assert.equal(G.overlaps(rect(0,0,4,4),rect(2,0,4,4)),true);assert.equal(G.overlaps(rect(0,0,4,4),rect(4,0,4,4)),false);});
test('a room inside another polygon hole is not overlapping its filled area',()=>assert.equal(G.overlaps({...rect(0,0,10,10),holes:[rect(2,2,6,6).points]},rect(3,3,2,2)),false));
test('scale disagreement blocks areas',()=>assert.throws(()=>G.metresPerUnit({...calibration,check:{start:[0,0],end:[5,0],metres:6}}),e=>e.code==='scale_disagreement'));
test('unconfirmed or zero scale is rejected',()=>{assert.throws(()=>G.metresPerUnit({...calibration,confirmed:false}));assert.throws(()=>G.metresPerUnit({...calibration,end:[0,0]}));});
test('insert closing edge preserves area; deletion requires three vertices',()=>{const p=rect(0,0,10,5);G.insertVertex(p.points,3);assert.equal(p.points.length,5);assert.equal(G.polygonArea(p),50);G.removeVertex(p.points,4);G.removeVertex(p.points,3);assert.throws(()=>G.removeVertex(p.points,2));});
test('seed-derived regions exactly follow synthetic enclosing walls',()=>{const r=R.segmentPlan(raster(),spaces(),[],config);assert.equal(r.regions.length,2);assert.deepEqual(r.issues,[]);assert.equal(r.regions[0].pixelArea,24*34);assert.equal(G.polygonArea(r.regions[0]),24*34);});
test('AI alternate seed is used if primary lies on ink',()=>{const s=spaces();s[0].seeds=[[5,5],[15,15]];const r=R.segmentPlan(raster(),s,[],config);assert.deepEqual(r.regions[0].seed,[15,15]);});
test('outside/open boundary region is refused, no imaginary closure',()=>{const r=R.segmentPlan(raster(),[{id:'outside',label:'X',kind:'room',seeds:[[1,1]]}],[],config);assert.equal(r.regions.length,0);assert.equal(r.issues[0].code,'seed_region_unresolved');});
test('duplicate balcony seeds yield one region, conflicting classification flagged',()=>{const s=spaces();s.push({...s[0],id:'duplicate',kind:'balcony'});const r=R.segmentPlan(raster(),s,[],config);assert.equal(r.regions.length,2);assert.deepEqual(r.duplicates,[{id:'duplicate',sameAs:'a'}]);assert.equal(r.issues[0].code,'duplicate_classification_conflict');});
test('raster limits and malformed coordinates are controlled',()=>{assert.throws(()=>R.segmentPlan({...raster(),width:0},spaces(),[],config));const s=spaces();s[0].seeds=[[NaN,2]];assert.equal(R.segmentPlan(raster(),s,[],config).issues[0].code,'seed_region_unresolved');});
test('principal surface + balcony 25% produces auditable rows',()=>{const p=base();p.surfaces.push({id:'balcony',kind:'uncovered_balcony',geometry:rect(20,0,8,1)});const r=C.commercialReport(p);assert.equal(r.totalM2,82);assert.equal(r.profile,'agency_commercial_custom');assert.equal(r.certification,false);});
test('coefficient range never silently chooses midpoint',()=>{const p=base();p.surfaces.push({id:'g',kind:'garage',geometry:rect(20,0,5,4)});const r=C.commercialReport(p);assert.equal(r.totalM2,null);assert.ok(r.issues.includes('coefficient_required:g'));assert.equal(r.partialM2,80);});
test('explicit coefficient and reason produce repeatable custom computation',()=>{const p=base();p.surfaces.push({id:'g',kind:'garage',geometry:rect(20,0,5,4),coefficient:.55,selectionReason:'Agency selected policy'});assert.equal(C.commercialReport(p).totalM2,91);p.surfaces[1].coefficient=.9;assert.throws(()=>C.commercialReport(p));});
test('coefficient reason required, missing policy/walls/symbol block final total',()=>{const p=base();p.surfaces.push({id:'g',kind:'garden',geometry:rect(20,0,5,4),coefficient:.1});p.wallCoverageConfirmed=false;p.policyConfirmed=false;p.unresolvedSymbols=['unknown-X'];const r=C.commercialReport(p);assert.equal(r.totalM2,null);assert.equal(r.issues.length,4);});
test('height below1.5 excluded; missing attic height does not invent it',()=>{const p=base();p.surfaces=[{id:'attic',kind:'uninhabitable_attic',geometry:rect(0,0,10,5),heightMetres:1.4}];assert.equal(C.commercialReport(p).totalM2,0);delete p.surfaces[0].heightMetres;assert.equal(C.commercialReport(p).totalM2,null);});
test('attic2.4 requires qualification confirmation and range choice',()=>{const p=base();p.surfaces=[{id:'attic',kind:'habitable_attic',geometry:rect(0,0,10,5),heightMetres:2.4,coefficient:.8,selectionReason:'Chosen',qualificationConfirmed:true}];assert.equal(C.commercialReport(p).totalM2,40);p.surfaces[0].heightMetres=2.3;assert.equal(C.commercialReport(p).totalM2,null);});
test('walls are once-only physical components; shared thickness basis is explicit',()=>{const p=base();p.walls=[{id:'wall',scope:'main_unit',kind:'shared',geometry:rect(20,0,10,.4),thicknessMetres:.4,uniformThicknessConfirmed:true}];assert.equal(C.commercialReport(p).totalM2,81.25);p.commonWallCapBasis='credited_thickness';assert.equal(C.commercialReport(p).totalM2,82);});
test('exclusive wall thickness capped50cm',()=>{const p=base();p.walls=[{id:'wall',scope:'main_unit',kind:'exclusive',geometry:rect(20,0,10,.8),thicknessMetres:.8,uniformThicknessConfirmed:true}];assert.equal(C.commercialReport(p).totalM2,85);});
test('overlapping surfaces/walls and unknown classifications block total',()=>{const p=base();p.walls=[{id:'wall',scope:'main_unit',kind:'unknown',geometry:rect(0,0,10,.2),thicknessMetres:.2,uniformThicknessConfirmed:true}];const r=C.commercialReport(p);assert.equal(r.totalM2,null);assert.ok(r.issues.includes('wall_classification_required:wall'));assert.ok(r.issues.includes('overlap:main:wall'));});
test('commercial gross perimeter preserves room detail without summing it twice',()=>{const p=base(),r=C.commercialPerimeterReport({...p,mainPerimeter:rect(0,0,10,10),roomBreakdown:[{id:'room',geometry:rect(1,1,8,8)}],accessories:[]});assert.equal(r.totalM2,100);assert.equal(r.roomBreakdown[0].netM2,64);assert.equal(r.base,'gross_perimeter');});
test('gross perimeter deducts uncredited shared wall instead of adding walls',()=>{const p=base();p.walls=[{id:'wall',scope:'main_unit',kind:'shared',geometry:rect(0,0,10,.2),thicknessMetres:.2,uniformThicknessConfirmed:true}];const r=C.commercialPerimeterReport({...p,mainPerimeter:rect(0,0,10,10),roomBreakdown:[],accessories:[]});assert.equal(r.totalM2,99);assert.equal(r.wallAdjustments[0].deductionM2,1);});
test('balcony overlapping gross or room outside gross blocks computation',()=>{const p=base(),r=C.commercialPerimeterReport({...p,mainPerimeter:rect(0,0,10,10),roomBreakdown:[{id:'room',geometry:rect(9,9,4,4)}],accessories:[{id:'balcony',kind:'uncovered_balcony',geometry:rect(9,9,4,4)}]});assert.equal(r.totalM2,null);assert.ok(r.issues.includes('room_outside_perimeter:room'));});
test('containment checks concave perimeter and holes',()=>{const p={points:[[0,0],[10,0],[10,3],[3,3],[3,10],[0,10]],holes:[]};assert.equal(G.within(rect(1,1,8,8),p),false);assert.equal(G.within(rect(1,1,1,1),p),true);});
function ports(extra={}){const proof={sourceId:'source',version:1,sha256:'a'.repeat(64),page:1},window={validFrom:'2026-01-01T00:00:00Z',validUntil:null,revokedAt:null};const ctx={now:'2026-10-30T00:00:00Z',actor:{accountId:'a',memberships:[{...window,agencyId:'agency',accountId:'a',role:'agent'}],grants:[{...window,agencyId:'agency',practiceId:'practice',accountId:'a',access:'edit',canExport:true}]},practice:{id:'practice',agencyId:'agency',label:'Synthetic',revision:1,sources:[{id:'source',practiceId:'practice',agencyId:'agency',uploaderId:'a',visibility:'private',withdrawnAt:null,kind:'floor_plan',versions:[{version:1,sha256:proof.sha256}]}],dependents:[],receipts:[],events:[]}};const calls=[],reserved=new Set(),settled=[];const adapter={context:async()=>ctx,loadRaster:async()=>raster(),reserve:async(run,phase)=>{const k=run+phase;if(reserved.has(k))throw Error('already_reserved');reserved.add(k);},settle:async(run,phase,usage)=>settled.push({run,phase,usage}),markUncertain:async()=>calls.push('uncertain'),ai:async request=>{calls.push(request.phase);return {proposal:{spaces:spaces(),symbols:[],warnings:[]},inputTokens:100,outputTokens:50,costUSD:.001,requestId:request.phase};},...extra};return {proof,ctx,calls,reserved,settled,adapter,input:{runId:'run',proof,config,maxUSDPerCall:.1}};}
test('two-call pipeline uses fresh source auth and returns draft only',async()=>{const f=ports(),r=await P.analyzePlan(f.adapter,f.input);assert.deepEqual(f.calls,['inventory','review']);assert.equal(r.final.regions.length,2);assert.equal(r.totalCostUSD,.002);assert.equal(r.confirmed,false);assert.equal(r.coverageConfirmed,false);assert.equal(f.settled.length,2);});
test('source replaced during AI is billed but its result is refused',async()=>{const f=ports();const original=f.adapter.ai;f.adapter.ai=async q=>{const r=await original(q);f.ctx.practice.sources[0].versions.push({version:2,sha256:'b'.repeat(64)});return r;};await assert.rejects(P.analyzePlan(f.adapter,f.input),e=>e.code==='plan_source_unavailable');assert.equal(f.settled.length,1);assert.equal(f.calls.length,1);});
test('revoked membership and private source reader denied without AI',async()=>{const f=ports();f.ctx.actor.memberships[0].revokedAt='2026-10-29T00:00:00Z';await assert.rejects(P.analyzePlan(f.adapter,f.input));assert.equal(f.calls.length,0);});
test('provider failure marks uncertain without retry',async()=>{const f=ports({ai:async()=>{throw Error('network');}});await assert.rejects(P.analyzePlan(f.adapter,f.input),/network/);assert.deepEqual(f.calls,['uncertain']);assert.equal(f.reserved.size,1);});
test('duplicate run reservation prevents paid repeat',async()=>{const f=ports();await P.analyzePlan(f.adapter,f.input);await assert.rejects(P.analyzePlan(f.adapter,f.input),/already_reserved/);assert.equal(f.calls.length,2);});
test('invalid AI JSON is settled before rejection',async()=>{const f=ports({ai:async()=>({proposal:{spaces:'bad'},inputTokens:1,outputTokens:1,costUSD:.001,requestId:'bad'})});await assert.rejects(P.analyzePlan(f.adapter,f.input));assert.equal(f.settled.length,1);});
test('over-budget response is settled and stopped before second call',async()=>{const f=ports();const original=f.adapter.ai;f.adapter.ai=async q=>({...await original(q),costUSD:.2});await assert.rejects(P.analyzePlan(f.adapter,f.input),e=>e.code==='provider_cost_exceeded');assert.equal(f.settled.length,1);});
test('no source kind or scope escalation across phases',async()=>{const f=ports();f.ctx.practice.sources[0].kind='deed';await assert.rejects(P.analyzePlan(f.adapter,f.input));assert.equal(f.calls.length,0);});
test('review cannot degrade previously valid symbol geometry silently',async()=>{const f=ports(),image=raster();for(let y=20;y<=30;y++)for(let x=5;x<=14;x++)if(x===5||x===14||y===20||y===30||x===9||y===25)image.gray[y*80+x]=0;f.adapter.loadRaster=async()=>image;f.adapter.ai=async q=>({proposal:{spaces:spaces(),symbols:[{id:'symbol',parentId:'a',decision:'include',reason:'Explicit test rule',seeds:q.phase==='inventory'?[[7,22],[11,22],[7,28],[11,28]]:[[5,20]]}],warnings:[]},inputTokens:1,outputTokens:1,costUSD:.001,requestId:q.phase});const r=await P.analyzePlan(f.adapter,f.input);assert.deepEqual(r.retainedSymbols,['symbol']);assert.equal(r.final.regions[0].symbols[0].status,'included');assert.ok(r.warnings.includes('retained_previous_symbol:symbol'));});
test('all user coefficient categories are available without hidden range defaults',()=>{for(const [kind,range]of Object.entries(C.COMMERCIAL_RULES)){const p=base();p.surfaces=[{id:'x',kind,geometry:rect(0,0,10,10),coefficient:range[0],selectionReason:'Policy choice',qualificationConfirmed:true,...(kind==='habitable_attic'?{heightMetres:2.4}:kind==='uninhabitable_attic'?{heightMetres:2}:{})}];assert.equal(C.commercialReport(p).totalM2,100*range[0],kind);}});
test('analysis snapshot replay is idempotent; changed result cannot replace history',async()=>{const f=ports(),analysis=await P.analyzePlan(f.adapter,f.input),r=Records.registerPlan(f.ctx.actor,f.ctx.practice,analysis,1,f.ctx.now);assert.equal(r.practice.revision,2);assert.equal(Records.registerPlan(f.ctx.actor,r.practice,analysis,1,f.ctx.now).replay,true);const changed=structuredClone(analysis);changed.final.regions[0].label='changed';assert.throws(()=>Records.registerPlan(f.ctx.actor,r.practice,changed,2,f.ctx.now),e=>e.code==='idempotency_conflict');});
test('private plan-derived geometry hidden from assigned admin; stale source hides geometry',async()=>{const f=ports(),analysis=await P.analyzePlan(f.adapter,f.input),p=Records.registerPlan(f.ctx.actor,f.ctx.practice,analysis,1,f.ctx.now).practice;const other=structuredClone(f.ctx.actor);other.accountId='b';other.memberships[0].accountId='b';other.memberships[0].role='admin';other.grants[0].accountId='b';assert.equal(Records.planViews(other,p,f.ctx.now).plans.length,0);p.sources[0].versions.push({version:2,sha256:'b'.repeat(64)});const view=Records.planViews(f.ctx.actor,p,f.ctx.now);assert.equal(view.plans[0].status,'stale');assert.equal(view.plans[0].rooms,null);assert.throws(()=>Records.registerPlan(f.ctx.actor,p,analysis,2,f.ctx.now),e=>e.code==='source_changed');});
test('lossless PNG contains exact source pixels, without external image services',()=>{const r=raster(),p=Provider.png(r);assert.deepEqual([...p.subarray(0,8)],[137,80,78,71,13,10,26,10]);let offset=8;const chunks=[];while(offset<p.length){const n=p.readUInt32BE(offset),type=p.toString('ascii',offset+4,offset+8);if(type==='IDAT')chunks.push(p.subarray(offset+8,offset+8+n));offset+=12+n;}const raw=require('node:zlib').inflateSync(Buffer.concat(chunks));assert.equal(raw.length,r.height*(r.width*3+1));for(let y=0;y<r.height;y++)for(let x=0;x<r.width;x++)assert.equal(raw[y*(r.width*3+1)+1+x*3],r.gray[y*r.width+x]);});
test('provider counts tokens and caps maximum cost before a generation',async()=>{const calls=[],ai=Provider.createPlanProvider({post:async endpoint=>{calls.push(endpoint);return {input_tokens:1000};}},{model:'claude-sonnet-5-5',inputUSDPerMillion:2,outputUSDPerMillion:10,maxOutputTokens:100,userRules:''});await assert.rejects(ai({phase:'inventory',raster:raster(),previous:null,segmentation:null,maxUSD:.0001}),e=>e.code==='plan_budget_insufficient');assert.deepEqual(calls,['messages/count_tokens']);});
test('provider incomplete output preserves usage so pipeline can settle a failed answer',async()=>{const ai=Provider.createPlanProvider({post:async endpoint=>endpoint==='messages/count_tokens'?{input_tokens:1000}:{id:'partial',stop_reason:'max_tokens',usage:{input_tokens:1000,output_tokens:100},content:[]}},{model:'claude-sonnet-5-5',inputUSDPerMillion:2,outputUSDPerMillion:10,maxOutputTokens:100,userRules:''});const r=await ai({phase:'inventory',raster:raster(),previous:null,segmentation:null,maxUSD:.1});assert.equal(r.proposal,null);assert.equal(r.costUSD,.003);});
test('invalid raster is rejected before reservation or paid call',async()=>{const f=ports({loadRaster:async()=>({width:1,height:1,gray:new Uint8Array(1)})});await assert.rejects(P.analyzePlan(f.adapter,f.input));assert.equal(f.reserved.size,0);assert.equal(f.calls.length,0);});
test('geometry edits preserve rooms/perimeter independently and invalidate stored computation',async()=>{const f=ports(),a=await P.analyzePlan(f.adapter,f.input);let p=Records.registerPlan(f.ctx.actor,f.ctx.practice,a,1,f.ctx.now).practice;const request={key:'edit-1',expectedRevision:2,expectedPlanVersion:1,planId:a.runId,reason:'Manual gross outline',command:{operation:'geometry',view:'perimeter',id:'gross',geometry:rect(0,0,75,50)}};p=Records.editPlan(f.ctx.actor,p,request,f.ctx.now).practice;assert.deepEqual(p.planAnalyses[0].rooms,a.final.regions);assert.deepEqual(p.planAnalyses[0].mainPerimeter,rect(0,0,75,50));assert.equal(p.planAnalyses[0].geometryRevision,2);assert.equal(p.planAnalyses[0].measurement,null);assert.equal(Records.editPlan(f.ctx.actor,p,request,f.ctx.now).replay,true);const bad={...request,key:'bad',expectedRevision:3,expectedPlanVersion:2,command:{...request.command,geometry:rect(0,0,1000,1000)}};assert.throws(()=>Records.editPlan(f.ctx.actor,p,bad,f.ctx.now));assert.equal(p.revision,3);});
test('private source cannot be edited by another assigned administrator',async()=>{const f=ports(),a=await P.analyzePlan(f.adapter,f.input),p=Records.registerPlan(f.ctx.actor,f.ctx.practice,a,1,f.ctx.now).practice,other=structuredClone(f.ctx.actor);other.accountId='b';other.memberships[0].accountId='b';other.memberships[0].role='admin';other.grants[0].accountId='b';assert.throws(()=>Records.editPlan(other,p,{key:'k',expectedRevision:2,expectedPlanVersion:1,planId:a.runId,reason:'Attempt',command:{operation:'geometry',view:'perimeter',id:'gross',geometry:rect(0,0,75,50)}},f.ctx.now),e=>e.code==='access_denied');});
test('geometry coverage is a separate gate even when polygons and walls look complete',()=>{const p=base();p.coverageConfirmed=false;const r=C.commercialReport(p);assert.equal(r.totalM2,null);assert.ok(r.issues.includes('coverage_not_confirmed'));});

test('manual partition clips selection to source room and preserves net area and holes',()=>{const {carveManualRoom}=require('../dist/agency-plans/manual-room');const parent={...rect(0,0,10,10),holes:[rect(6,6,1,1).points]},before=structuredClone(parent),r=carveManualRoom(parent,rect(-2,-2,6,14));assert.equal(G.polygonArea(r.added),40);assert.equal(G.polygonArea(r.remaining),59);assert.equal(G.overlaps(r.added,r.remaining),false);assert.deepEqual(parent,before);assert.equal(r.remaining.holes.length,1);});
test('manual partition rejects empty, total and disconnected results without dropping islands',()=>{const {carveManualRoom}=require('../dist/agency-plans/manual-room');for(const selection of [rect(20,20,1,1),rect(-1,-1,12,12),rect(4,-1,2,12)])assert.throws(()=>carveManualRoom(rect(0,0,10,10),selection));});
test('manual room creation is idempotent, preserves others/perimeter and invalidates computation',async()=>{const f=ports(),analysis=await P.analyzePlan(f.adapter,f.input),original=Records.registerPlan(f.ctx.actor,f.ctx.practice,analysis,1,f.ctx.now).practice;const input={key:'manual-create',planId:analysis.runId,expectedRevision:2,expectedPlanVersion:1,reason:'Synthetic missing room',command:{operation:'add_room',id:'manual',label:'New room',kind:'room',geometry:rect(4,45,10,8)}};const before=structuredClone(original),r=Records.editPlan(f.ctx.actor,original,input,f.ctx.now);assert.equal(r.practice.planAnalyses[0].rooms.length,3);assert.deepEqual(r.practice.planAnalyses[0].rooms.slice(0,2),before.planAnalyses[0].rooms);assert.equal(r.practice.planAnalyses[0].rooms[2].origin,'manual');assert.equal(r.practice.planAnalyses[0].rooms[2].seed,null);assert.equal(r.practice.planAnalyses[0].measurement,null);assert.equal(r.practice.planAnalyses[0].measurementConfiguration,null);assert.equal(Records.editPlan(f.ctx.actor,r.practice,input,f.ctx.now).replay,true);assert.deepEqual(original,before);});
test('carving a manual corridor updates only its parent and preserves aggregate geometry area',async()=>{const f=ports(),a=await P.analyzePlan(f.adapter,f.input),p=Records.registerPlan(f.ctx.actor,f.ctx.practice,a,1,f.ctx.now).practice,old=p.planAnalyses[0],room=old.rooms[0],area=G.polygonArea(room);const r=Records.editPlan(f.ctx.actor,p,{key:'carve',planId:a.runId,expectedRevision:2,expectedPlanVersion:1,reason:'Separate corridor',command:{operation:'add_room',id:'hall',label:'Hall',kind:'corridor',parentId:room.id,geometry:rect(0,0,15,45)}},f.ctx.now).practice.planAnalyses[0];assert.equal(r.rooms.length,3);assert.equal(G.overlaps(r.rooms[0],r.rooms[2]),false);assert.ok(Math.abs(G.polygonArea(r.rooms[0])+G.polygonArea(r.rooms[2])-area)<.001);assert.deepEqual(r.rooms[1],old.rooms[1]);assert.deepEqual(r.mainPerimeter,old.mainPerimeter);assert.equal(r.rooms[2].derivedFrom,room.id);assert.equal(r.edits[0].rooms.length,2);});
test('manual room rejects overlapping addition, wrong parent, stale revision and outside-image coordinates',async()=>{const f=ports(),a=await P.analyzePlan(f.adapter,f.input),p=Records.registerPlan(f.ctx.actor,f.ctx.practice,a,1,f.ctx.now).practice;const request={key:'invalid',planId:a.runId,expectedRevision:2,expectedPlanVersion:1,reason:'Synthetic',command:{operation:'add_room',id:'new',label:'New',kind:'room',geometry:rect(10,10,5,5)}};assert.throws(()=>Records.editPlan(f.ctx.actor,p,request,f.ctx.now),e=>e.code==='region_overlap');assert.throws(()=>Records.editPlan(f.ctx.actor,p,{...request,command:{...request.command,parentId:'absent'}},f.ctx.now));assert.throws(()=>Records.editPlan(f.ctx.actor,p,{...request,expectedRevision:1},f.ctx.now),e=>e.code==='revision_conflict');assert.throws(()=>Records.editPlan(f.ctx.actor,p,{...request,command:{...request.command,geometry:rect(79,59,5,5)}},f.ctx.now));assert.equal(p.planAnalyses[0].rooms.length,2);});
test('same-kind room masks cannot silently hide a second semantic space',()=>{const s=spaces();s[1]={id:'missing-hall',kind:'room',label:'Other space',seeds:[[16,16]]};const r=R.segmentPlan(raster(),s,[],config);assert.equal(r.regions.length,1);assert.ok(r.issues.some(i=>i.code==='semantic_regions_merged'));});

test('pixel-disjoint synthetic diagonal rooms remain polygon-disjoint after simplification',()=>{const width=64,height=56,gray=new Uint8Array(width*height).fill(255);for(let y=0;y<height;y++)for(let x=0;x<width;x++)if(x<3||x>60||y<3||y>52)gray[y*width+x]=0;let value=2,edge=30;for(let y=3;y<=52;y++){value=(value*1664525+1013904223)>>>0;const prior=edge;edge=Math.max(23,Math.min(40,edge+(value%3)-1));for(let x=Math.min(prior,edge);x<=Math.max(prior,edge);x++)gray[y*width+x]=0;}const input={width,height,gray},before=Buffer.from(gray),s=[{id:'left',label:'Left',kind:'room',seeds:[[10,20]]},{id:'right',label:'Right',kind:'room',seeds:[[50,20]]}],r=R.segmentPlan(input,s,[],{...config,simplifyPixels:3,maxRegionFraction:.9});assert.equal(r.regions.length,2);assert.equal(G.overlaps(...r.regions),false);assert.ok(r.regions.some(s=>s.boundary.refinedForOverlap));assert.ok(r.diagnostics.some(d=>d.code==='boundary_refined'));assert.deepEqual(Buffer.from(gray),before);const reversed=R.segmentPlan(input,[...s].reverse(),[],{...config,simplifyPixels:3,maxRegionFraction:.9});assert.equal(reversed.regions.length,2);assert.equal(G.overlaps(...reversed.regions),false);for(const room of r.regions)assert.equal(room.pixelArea,reversed.regions.find(s=>s.id===room.id).pixelArea);});
test('seed diagnostics distinguish invalid, outside, ink, open exterior, small and large components',()=>{const r=raster(),samples=[{id:'bad',kind:'room',label:'Bad',seeds:[[NaN,2],[1000,2],[5,5]]},{id:'small',kind:'room',label:'Small',seeds:[[15,15]]},{id:'excluded',kind:'excluded',label:'Separate annex',seeds:[[45,15]]}];const a=R.segmentPlan(r,[...samples,{id:'open',kind:'room',label:'Exterior',seeds:[[1,1]]}],[],{...config,minRegionPixels:1000});assert.deepEqual(a.diagnostics.filter(d=>d.id==='bad').map(d=>d.code),['invalid_seed','outside_image','on_ink']);assert.ok(a.diagnostics.some(d=>d.id==='open'&&d.code==='open_to_border'));assert.ok(a.diagnostics.some(d=>d.id==='small'&&d.code==='too_small'));assert.ok(a.diagnostics.some(d=>d.id==='excluded'&&d.code==='proposal_excluded'));const b=R.segmentPlan(r,[samples[1]],[],{...config,maxRegionFraction:.01});assert.equal(b.diagnostics[0].code,'too_large');assert.equal(b.regions.length,0);});
test('successful alternative retains failed seed diagnosis and accepted seed index',()=>{const s=spaces();s[0].seeds=[[5,5],[15,15]];const r=R.segmentPlan(raster(),s,[],config);assert.deepEqual(r.diagnostics.filter(d=>d.id==='a').map(d=>[d.code,d.seedIndex]),[['on_ink',0],['seed_accepted',1]]);assert.equal(r.regions[0].boundary.refinedForOverlap,false);});
test('registration rejects overlapping final polygons even from an internal pipeline result',async()=>{const f=ports(),a=await P.analyzePlan(f.adapter,f.input);a.final.regions[1].points=structuredClone(a.final.regions[0].points);a.final.regions[1].holes=structuredClone(a.final.regions[0].holes);assert.throws(()=>Records.registerPlan(f.ctx.actor,f.ctx.practice,a,1,f.ctx.now),e=>e.code==='region_overlap');assert.equal(f.ctx.practice.planAnalyses,undefined);});
test('analysis diagnostics persist under source scope; manual contour changes clear automatic boundary provenance',async()=>{const f=ports(),a=await P.analyzePlan(f.adapter,f.input),saved=Records.registerPlan(f.ctx.actor,f.ctx.practice,a,1,f.ctx.now).practice;assert.deepEqual(saved.planAnalyses[0].analysisDiagnostics,a.final.diagnostics);const changed=Records.editPlan(f.ctx.actor,saved,{key:'boundary-metadata',planId:a.runId,expectedRevision:2,expectedPlanVersion:1,reason:'Manual contour review',command:{operation:'geometry',view:'rooms',id:'a',geometry:rect(6,6,20,30)}},f.ctx.now).practice.planAnalyses[0].rooms[0];assert.equal(changed.origin,'manual');assert.equal(changed.boundary,undefined);assert.equal(changed.seed,null);});

const Recognition=require('../dist/agency-plans/recognition-rules');
function entranceRaster(){const width=80,height=80,gray=new Uint8Array(width*height).fill(255);for(let x=15;x<=65;x++){if(x<35||x>45)gray[15*width+x]=0;gray[65*width+x]=0;}for(let y=15;y<=65;y++){gray[y*width+15]=0;gray[y*width+65]=0;}return {width,height,gray};}
const opening=()=>({id:'entrance',start:[34,15],end:[46,15],signals:['wall_ends','arrow'],context:'inside_to_common',source:'ai'});
test('annex labels generalize across cellar, garage, parking and attic without ownership or coefficient',()=>{for(const [text,kind]of[['CANTINA piano S1','cellar'],['Box auto','garage'],['autorimessa privata','garage'],['posto auto scoperto','parking'],['Soffitta non abitabile','attic'],['BALCONE','balcony'],['terrazza','terrace'],['giardino','garden']]){const r=Recognition.classifyAnnex(text,.9);assert.equal(r.kind,kind);assert.equal(r.association,'unverified');assert.equal(r.status,'proposed');assert.equal(r.coefficient,undefined);}assert.equal(Recognition.classifyAnnex('box',.95).kind,null);assert.equal(Recognition.classifyAnnex('cantina e garage',.95).kind,null);assert.equal(Recognition.classifyAnnex('non cantina',.95).kind,null);assert.equal(Recognition.classifyAnnex('cantina',.3).kind,null);assert.equal(Recognition.classifyAnnex('garage condominiale',.95).association,'other_or_common_to_verify');});
test('a separately drawn annex marked excluded remains in the review census without changing its input',()=>{const input=[{id:'cellar',label:'cantina separata',kind:'excluded',seeds:[[10,10]]}],before=structuredClone(input),r=Recognition.annexCensus(input);assert.equal(r[0].kind,'cellar');assert.equal(r[0].reviewExclusion,true);assert.equal(r[0].geometryAvailable,false);assert.deepEqual(input,before);});
test('entrance arrow requires context and supported wall ends; arrow alone never establishes an entrance',()=>{const r=entranceRaster(),p=Recognition.proposeThresholds(r,[opening()])[0];assert.equal(p.role,'entrance_candidate');assert.equal(p.state,'proposed');assert.equal(p.canPreview,true);const alone=Recognition.proposeThresholds(r,[{...opening(),signals:['arrow'],context:'unknown'}])[0];assert.equal(alone.role,'unclassified_opening');assert.equal(alone.canPreview,false);const internal=Recognition.proposeThresholds(r,[{...opening(),signals:['wall_ends','door_arc'],context:'between_rooms'}])[0];assert.equal(internal.role,'internal_door_candidate');assert.equal(internal.canPreview,true);});
test('virtual entrance closes only an explicitly selected preview copy, preserving the original pixels',()=>{const r=entranceRaster(),before=Buffer.from(r.gray),s=[{id:'inside',label:'Interior',kind:'room',seeds:[[40,40]]}],cfg={...config,minRegionPixels:10,maxRegionFraction:.9};assert.equal(R.segmentPlan(r,s,[],cfg).regions.length,0);const candidates=Recognition.proposeThresholds(r,[opening()]),none=Recognition.previewVirtualThresholds(r,candidates,[]);assert.deepEqual(none.raster.gray,r.gray);const preview=Recognition.previewVirtualThresholds(r,candidates,['entrance']);assert.equal(preview.state,'preview_only');assert.equal(preview.requiresConfirmation,true);assert.equal(R.segmentPlan(preview.raster,s,[],cfg).regions.length,1);assert.deepEqual(Buffer.from(r.gray),before);assert.ok(preview.changedPixels>0);assert.throws(()=>Recognition.previewVirtualThresholds(r,candidates,['absent']));assert.throws(()=>Recognition.previewVirtualThresholds(r,candidates,['entrance','entrance']));});
test('wall crossing, unsupported endpoints, overlong gaps and forged preview flags are rejected',()=>{const r=entranceRaster(),solid=Recognition.proposeThresholds(r,[{...opening(),start:[15,65],end:[35,65]}])[0];assert.equal(solid.canPreview,false);assert.ok(solid.reasons.includes('crosses_existing_ink'));const unknown=Recognition.proposeThresholds(r,[{...opening(),start:[20,30],end:[30,30]}])[0];assert.equal(unknown.canPreview,false);assert.throws(()=>Recognition.previewVirtualThresholds(r,[{...unknown,canPreview:true}],['entrance']));assert.throws(()=>Recognition.proposeThresholds(r,[{...opening(),end:[80,15]}]));assert.equal(Recognition.proposeThresholds(r,[{...opening(),end:[65,65]}])[0].canPreview,false);});
test('generic line-gap detector proposes openings without asserting doors, arrow recognition or ownership',()=>{const r=entranceRaster();for(let y=15;y<=21;y++){r.gray[y*80+34]=0;r.gray[y*80+46]=0;}const input=Buffer.from(r.gray),gaps=Recognition.detectOpeningGaps(r,{x:10,y:10,width:60,height:60},{limit:20});assert.ok(gaps.some(o=>Math.abs((o.start[0]+o.end[0])/2-40)<5&&Math.abs((o.start[1]+o.end[1])/2-15)<3));assert.ok(gaps.every(o=>o.context==='unknown'&&o.signals.length===1&&o.signals[0]==='wall_ends'));assert.deepEqual(Buffer.from(r.gray),input);assert.throws(()=>Recognition.detectOpeningGaps(r,{x:0,y:0,width:81,height:80}));});
test('pipeline flags an excluded cellar for review and persists the proposed census under source scope',async()=>{const f=ports(),baseAi=f.adapter.ai;f.adapter.ai=async request=>{const r=await baseAi(request);r.proposal.spaces.push({id:'cellar-inset',label:'Cantina separata',kind:'excluded',seeds:[[1,1]]});return r;};const a=await P.analyzePlan(f.adapter,f.input);assert.equal(a.annexInventory[0].reviewExclusion,true);assert.equal(a.annexInventory[0].association,'unverified');assert.ok(a.warnings.includes('annex_exclusion_requires_review:cellar-inset'));const saved=Records.registerPlan(f.ctx.actor,f.ctx.practice,a,1,f.ctx.now).practice;assert.deepEqual(saved.planAnalyses[0].annexInventory,a.annexInventory);const other=structuredClone(f.ctx.actor);other.accountId='b';other.memberships[0].accountId='b';other.grants[0].accountId='b';assert.equal(Records.planViews(other,saved,f.ctx.now).plans.length,0);});
test('a bare BOX label remains an ambiguous accessory candidate rather than disappearing from census',()=>{const a=Recognition.classifyAnnex('BOX',.99);assert.equal(a.kind,null);assert.deepEqual(a.candidates,['garage']);assert.equal(a.reason,'ambiguous_box');const census=Recognition.annexCensus([{id:'box',label:'BOX',kind:'excluded',seeds:[[1,1]]}]);assert.equal(census.length,1);assert.equal(census[0].reviewExclusion,true);});
test('a plain broken underline without jamb branches is not promoted to an opening proposal',()=>{const width=80,height=80,gray=new Uint8Array(width*height).fill(255);for(let x=15;x<=65;x++)if(x<35||x>45)gray[40*width+x]=0;assert.deepEqual(Recognition.detectOpeningGaps({width,height,gray},{x:10,y:10,width:60,height:60}),[]);});
test('provider review receives excluded annex candidates as proposals, without rewriting the original inventory',async()=>{let body;const previous={spaces:[{id:'cellar',label:'Cantina separata',kind:'excluded',seeds:[[10,10]]}],symbols:[],warnings:[]},before=structuredClone(previous),ai=Provider.createPlanProvider({post:async(endpoint,b)=>{if(endpoint==='messages/count_tokens'){body=b;return {input_tokens:10};}return {id:'synthetic-annex-review',stop_reason:'end_turn',usage:{input_tokens:10,output_tokens:10},content:[{type:'text',text:JSON.stringify(previous)}]};}},{model:'claude-sonnet-5-5',inputUSDPerMillion:2,outputUSDPerMillion:10,maxOutputTokens:100,userRules:''});await ai({phase:'review',raster:raster(),previous,segmentation:null,maxUSD:.1});const context=JSON.parse(body.messages[0].content.find(c=>c.type==='text').text);assert.equal(context.annexReviewCandidates[0].reviewExclusion,true);assert.equal(context.annexReviewCandidates[0].association,'unverified');assert.deepEqual(previous,before);});
test('explicit annex exclusion can yield a geometric candidate without asserting association or mutating model output',()=>{const input=[{id:'cellar',kind:'excluded',label:'Cantina separata',seeds:[[15,15]]},{id:'garage',kind:'excluded',label:'Garage condominiale',seeds:[[45,15]]},{id:'box',kind:'excluded',label:'BOX',seeds:[[15,15]]},{id:'other',kind:'excluded',label:'Cantina altra unita',seeds:[[15,15]]}],before=structuredClone(input),recovered=Recognition.recoverAnnexInventory(input);assert.equal(recovered[0].kind,'room');assert.equal(recovered[1].kind,'excluded');assert.equal(recovered[2].kind,'excluded');assert.equal(recovered[3].kind,'excluded');assert.deepEqual(input,before);const census=Recognition.annexCensus(input,['cellar']);assert.equal(census[0].geometryAvailable,true);assert.equal(census[0].association,'unverified');assert.equal(census[0].reviewExclusion,true);});
test('pipeline recovers a labelled excluded cellar contour while retaining raw exclusion and unverified association',async()=>{const f=ports();f.adapter.ai=async request=>({proposal:{spaces:[spaces()[0],{id:'cellar',label:'Cantina separata',kind:'excluded',seeds:[[45,15]]}],symbols:[],warnings:[]},inputTokens:10,outputTokens:10,costUSD:.001,requestId:request.phase});const a=await P.analyzePlan(f.adapter,f.input);assert.equal(a.final.regions.length,2);assert.equal(a.final.regions.find(r=>r.id==='cellar').kind,'room');assert.equal(a.proposal.spaces.find(r=>r.id==='cellar').kind,'excluded');assert.equal(a.annexInventory[0].geometryAvailable,true);assert.equal(a.annexInventory[0].association,'unverified');assert.equal(a.status,'needs_review');assert.equal(a.confirmed,false);});

const Surfaces=require('../dist/agency-plans/room-surfaces');
function inwardDoorRoom(){const points=[[0,0],[60,0],[60,50],[35,50],[35,45],[30,45],[30,50],[0,50],[0,30]];for(let i=14;i>=0;i--){const angle=i*Math.PI/30;points.push([20*Math.cos(angle),10+20*Math.sin(angle)]);}points.push([0,10]);return {id:'door-room',label:'Synthetic room',points,holes:[rect(40,20,3,3).points]};}
const inwardHint=()=>({roomId:'door-room',opensIntoRoomId:'door-room',hinge:[0,10],jambStart:[0,30],jambEnd:[0,10],radiusPixels:20,inkTolerancePixels:1});
test('inward door repair includes the swing floor while preserving all unrelated recesses and structural voids',()=>{const room=inwardDoorRoom(),before=structuredClone(room),out=Surfaces.repairInwardDoorBoundary(room,inwardHint());assert.equal(G.validPolygon(out.geometry),true);assert.ok(Math.abs(G.polygonArea(out.geometry)-(60*50-25-9))<1e-7);assert.deepEqual(out.geometry.holes,room.holes);assert.ok(out.geometry.points.some(p=>p[0]===35&&p[1]===45));assert.equal(out.state,'proposed');assert.equal(out.requiresInteriorReview,true);assert.deepEqual(room,before);});
test('a wrong swing side, unanchored jamb or ambiguous whole-room patch is rejected',()=>{const room=inwardDoorRoom();assert.throws(()=>Surfaces.repairInwardDoorBoundary(room,{...inwardHint(),opensIntoRoomId:'other'}),e=>e.code==='door_swing_room_mismatch');assert.throws(()=>Surfaces.repairInwardDoorBoundary(room,{...inwardHint(),jambStart:[8,8]}));assert.throws(()=>Surfaces.repairInwardDoorBoundary(room,{...inwardHint(),radiusPixels:500}));});
test('fixture strokes do not erode a selected wall envelope and explicit structural holes remain excluded',()=>{const r=raster();for(let x=10;x<=22;x++){r.gray[10*80+x]=0;r.gray[32*80+x]=0;}for(let y=10;y<=32;y++){r.gray[y*80+10]=0;r.gray[y*80+22]=0;}const before=Buffer.from(r.gray),e={id:'a',label:'Surface A',geometry:{...rect(6,6,24,34),holes:[rect(25,30,2,2).points]},source:'human_review',state:'proposed',wallSupport:[],requiresInteriorReview:true},old=R.segmentPlan(r,spaces(),[],config),preview=Surfaces.previewRoomSurfaces(r,spaces(),[],config,[e],['a']),room=preview.segmentation.regions.find(s=>s.id==='a');assert.ok(G.polygonArea(old.regions[0])<G.polygonArea(room));assert.equal(G.polygonArea(room),812);assert.deepEqual(room.holes,e.geometry.holes);assert.equal(room.seed,null);assert.equal(room.pixelArea,null);assert.equal(room.surfaceBasis,'wall_envelope');assert.deepEqual(preview.segmentation.regions.find(s=>s.id==='b'),old.regions.find(s=>s.id==='b'));assert.deepEqual(Buffer.from(r.gray),before);assert.equal(preview.confirmed,false);assert.equal(preview.totalM2,null);});
test('surface previews require explicit selection and refuse overlapping envelope assignments',()=>{const r=raster(),e={id:'a',label:'A',geometry:rect(6,6,24,34),source:'human_review',state:'proposed',wallSupport:[],requiresInteriorReview:true};assert.equal(Surfaces.previewRoomSurfaces(r,spaces(),[],config,[e],[]).envelopes.length,0);assert.throws(()=>Surfaces.previewRoomSurfaces(r,spaces(),[],config,[e],['missing']));assert.throws(()=>Surfaces.previewRoomSurfaces(r,spaces(),[],config,[e,{...e,id:'other'}],['a','other']),e=>e.code==='surface_envelope_overlap');});
test('a proposed strip that splits another room fails rather than discarding a fragment',()=>{const r=raster(),e={id:'new',label:'Wrong strip',geometry:rect(40,6,5,34),source:'human_review',state:'proposed',wallSupport:[],requiresInteriorReview:true};assert.throws(()=>Surfaces.previewRoomSurfaces(r,spaces(),[],config,[e],['new']),e=>e.code==='manual_room_multiple_components');});
test('four wall bands recover two adjacent service envelopes despite thin internal fixture strokes',()=>{const width=110,height=110,gray=new Uint8Array(width*height).fill(255);for(let y=0;y<height;y++)for(let x=0;x<width;x++)if((x>=15&&x<=17||x>=90&&x<=92)&&y>=15&&y<=90||(y>=15&&y<=17||y>=51&&y<=53||y>=89&&y<=91)&&x>=15&&x<=92)gray[y*width+x]=0;for(let x=30;x<70;x++){gray[30*width+x]=0;gray[42*width+x]=0;}for(let y=30;y<=42;y++){gray[y*width+30]=0;gray[y*width+69]=0;}const input={width,height,gray},before=Buffer.from(gray),c=Surfaces.detectRectangularWallEnvelopes(input,{center:[54,54],angleDegrees:0,halfWidth:45,halfHeight:45});assert.equal(c.length,2);assert.ok(c.every(e=>G.polygonArea(e.geometry)>1800));assert.equal(G.overlaps(c[0].geometry,c[1].geometry),false);assert.deepEqual(Buffer.from(gray),before);});
test('shared diagonal decimals tolerate floating point noise but real overlap remains detected',()=>{const angle=Math.PI/7,transform=p=>({points:p.points.map(([x,y])=>[10.123+x*Math.cos(angle)-y*Math.sin(angle),20.456+x*Math.sin(angle)+y*Math.cos(angle)]),holes:[]}),a=transform(rect(0,0,10,10)),b=transform(rect(10,0,10,10));b.points[0][0]-=1e-12;assert.equal(G.overlaps(a,b),false);assert.equal(G.overlaps(a,transform(rect(10-1e-5,0,10,10))),true);});
test('surface envelope provenance and unique identity cannot be bypassed by a forged candidate flag',()=>{const r=raster(),e={id:'a',label:'A',geometry:rect(6,6,24,34),source:'human_review',state:'proposed',wallSupport:[],requiresInteriorReview:true};assert.throws(()=>Surfaces.previewRoomSurfaces(r,spaces(),[],config,[{...e,requiresInteriorReview:false}],['a']));assert.throws(()=>Surfaces.previewRoomSurfaces(r,spaces(),[],config,[e,e],['a']));assert.throws(()=>Surfaces.previewRoomSurfaces(r,spaces(),[],config,[{...e,source:'certified'}],['a']));});
test('surface recovery keeps unknown symbols open and cannot fill an explicitly excluded structural area',()=>{const r=raster(),e={id:'a',label:'A',geometry:rect(6,6,24,34),source:'human_review',state:'proposed',wallSupport:[],requiresInteriorReview:true},symbol={id:'unknown',parentId:'a',decision:'unresolved',reason:'Unclassified feature',seeds:[[15,15]]},p=Surfaces.previewRoomSurfaces(r,spaces(),[symbol],config,[e],['a']);assert.ok(p.segmentation.issues.some(i=>i.id==='unknown'&&i.code==='symbol_unresolved'));assert.ok(p.segmentation.issues.some(i=>i.id==='a'&&i.code==='surface_interior_review_required'));assert.throws(()=>Surfaces.previewRoomSurfaces(r,spaces(),[{...symbol,decision:'exclude'}],config,[e],['a']),e=>e.code==='surface_excluded_symbol_requires_void_geometry');const voidEnvelope={...e,geometry:{...e.geometry,holes:[rect(13,13,4,4).points]}},withVoid=Surfaces.previewRoomSurfaces(r,spaces(),[{...symbol,decision:'exclude'}],config,[voidEnvelope],['a']);assert.equal(G.polygonArea(withVoid.segmentation.regions.find(r=>r.id==='a')),800);});
test('small valid polygons still detect a real thin overlap with segment-length-scaled tolerance',()=>{const a=rect(0,0,.01,.01),b=rect(.01-1e-6,0,.01,.01);assert.equal(G.validPolygon(a),true);assert.equal(G.validPolygon(b),true);assert.equal(G.overlaps(a,b),true);assert.equal(G.overlaps(a,rect(.01,0,.01,.01)),false);});

const OpeningRecovery=require('../dist/agency-plans/opening-recovery');
function recoveryFixture(){const r=entranceRaster();for(const x of[34,46])for(let y=15;y<=23;y++)r.gray[y*80+x]=0;const hint={id:'entry-auto',spaceId:'entry',nearStart:[34,15],nearEnd:[46,15],inside:[40,35],outside:[40,5],signal:'arrow',context:'inside_to_common'},s=[{id:'entry',label:'Entrance',kind:'corridor',seeds:[[40,35]]}],cfg={...config,minRegionPixels:10,maxRegionFraction:.9};return{r,hint,s,cfg};}
test('automatic opening refinement uses supported jambs and preserves original bytes',()=>{const f=recoveryFixture(),bytes=Buffer.from(f.r.gray),p=OpeningRecovery.refineOpening(f.r,f.hint);assert.equal(p.state,'proposed_recovery');assert.deepEqual(p.threshold.start,[34,15]);assert.deepEqual(p.threshold.end,[46,15]);const out=OpeningRecovery.recoverOpenings(f.r,f.s,[],f.cfg,[f.hint]);assert.deepEqual(out.applied,['entry-auto']);assert.equal(out.segmentation.regions.length,1);assert.equal(out.confirmed,false);assert.deepEqual(Buffer.from(f.r.gray),bytes);});
test('approximate door observations snap to nearby supported jamb pixels',()=>{const f=recoveryFixture(),out=OpeningRecovery.refineOpening(f.r,{...f.hint,nearStart:[33,14],nearEnd:[47,14]});assert.equal(out.state,'proposed_recovery');assert.ok(Math.hypot(out.threshold.start[0]-34,out.threshold.start[1]-15)<=2);});
test('a scan break without perpendicular jamb support does not become a door',()=>{const f=recoveryFixture();f.r=entranceRaster();const out=OpeningRecovery.recoverOpenings(f.r,f.s,[],f.cfg,[f.hint]);assert.deepEqual(out.applied,[]);assert.equal(out.reviews[0].state,'needs_review');assert.equal(out.segmentation.regions.length,0);});
test('arrow hints with same-side points, ink seeds or out-of-image geometry remain review items',()=>{const f=recoveryFixture();for(const patch of[{outside:[45,35]},{inside:[15,15]},{nearStart:[-1,15]}]){const out=OpeningRecovery.refineOpening(f.r,{...f.hint,...patch});assert.equal(out.state,'needs_review');assert.equal(out.threshold,null);}});
test('closing an arrow candidate never includes a separately excluded common-space seed',()=>{const f=recoveryFixture();f.s.push({id:'common',label:'Common stairs',kind:'excluded',seeds:[[20,20]]});const out=OpeningRecovery.recoverOpenings(f.r,f.s,[],f.cfg,[f.hint]);assert.deepEqual(out.applied,[]);assert.ok(out.reviews[0].reasons.includes('opening_includes_excluded_space'));});
test('continuous floor recovery retains separate semantic census conflict',()=>{const f=recoveryFixture();f.s.push({id:'living',label:'Living room',kind:'room',seeds:[[50,35]]});const out=OpeningRecovery.recoverOpenings(f.r,f.s,[],f.cfg,[f.hint]);assert.equal(out.applied.length,1);assert.ok(out.reviews[0].reasons.includes('opening_semantic_partition_required'));assert.ok(out.segmentation.issues.some(i=>i.code==='duplicate_classification_conflict'));});
test('duplicate opening IDs, forged signal and excessive hint count are refused',()=>{const f=recoveryFixture();assert.throws(()=>OpeningRecovery.recoverOpenings(f.r,f.s,[],f.cfg,[f.hint,f.hint]));assert.throws(()=>OpeningRecovery.refineOpening(f.r,{...f.hint,signal:'window'}));assert.throws(()=>OpeningRecovery.recoverOpenings(f.r,f.s,[],f.cfg,Array.from({length:13},(_,i)=>({...f.hint,id:String(i)}))));});
test('opening parser accepts old responses and rejects malformed new observations',()=>{const f=recoveryFixture(),base={spaces:f.s,symbols:[],warnings:[]};assert.equal(P.parseSeedProposal(base).openings,undefined);assert.deepEqual(P.parseSeedProposal({...base,openings:[f.hint]}).openings,[f.hint]);assert.throws(()=>P.parseSeedProposal({...base,openings:[{...f.hint,spaceId:'missing'}]}));assert.throws(()=>P.parseSeedProposal({...base,openings:[{...f.hint,inside:[NaN,0]}]}));});
test('two-call pipeline recovers an entrance draft and persists review evidence scoped to its source',async()=>{const f=ports(),fixture=recoveryFixture();f.adapter.loadRaster=async()=>fixture.r;let count=0;f.adapter.ai=async()=>{count++;return{proposal:{spaces:fixture.s,symbols:[],warnings:[],openings:[fixture.hint]},inputTokens:10,outputTokens:10,costUSD:.001,requestId:'opening-'+count};};f.input.config=fixture.cfg;const out=await P.analyzePlan(f.adapter,f.input);assert.equal(count,2);assert.equal(out.final.regions.length,1);assert.equal(out.status,'needs_review');assert.ok(out.final.issues.some(i=>i.code==='opening_recovery_requires_review'));const saved=Records.registerPlan(f.ctx.actor,f.ctx.practice,out,1,f.ctx.now).practice;assert.deepEqual(saved.planAnalyses[0].openingReviews,out.openingReviews);assert.equal(saved.planAnalyses[0].confirmed,false);const actor=structuredClone(f.ctx.actor);actor.accountId='b';actor.memberships[0].accountId='b';actor.grants[0].accountId='b';assert.equal(Records.planViews(actor,saved,f.ctx.now).plans.length,0);});
test('opening recovery is rotation-independent for a quarter-turned drawing',()=>{const f=recoveryFixture(),gray=new Uint8Array(f.r.gray.length);for(let y=0;y<80;y++)for(let x=0;x<80;x++)gray[x*80+79-y]=f.r.gray[y*80+x];const turn=p=>[79-p[1],p[0]],h={...f.hint,nearStart:turn(f.hint.nearStart),nearEnd:turn(f.hint.nearEnd),inside:turn(f.hint.inside),outside:turn(f.hint.outside)},s=f.s.map(s=>({...s,seeds:s.seeds.map(turn)})),out=OpeningRecovery.recoverOpenings({...f.r,gray},s,[],f.cfg,[h]);assert.equal(out.applied.length,1);assert.deepEqual(out.segmentation.regions[0].boundary.virtualThresholdIds,['entry-auto']);});
test('uncertain or missing hints never trigger blanket gap closure',()=>{const f=recoveryFixture(),out=OpeningRecovery.recoverOpenings(f.r,f.s,[],f.cfg,[]);assert.equal(out.segmentation.regions.length,0);assert.deepEqual(out.reviews,[]);const p=OpeningRecovery.refineOpening(f.r,f.hint,180,'human');assert.equal(p.hintSource,'human');assert.equal(p.endpointSource,'pixel_refinement');assert.equal(p.threshold.source,'human');});
test('provider requests door evidence within its existing generation budget, not another call',async()=>{let body;const ai=Provider.createPlanProvider({post:async(endpoint,b)=>{if(endpoint==='messages/count_tokens'){body=b;return{input_tokens:10};}return{id:'synthetic-openings',stop_reason:'end_turn',usage:{input_tokens:10,output_tokens:10},content:[{type:'text',text:JSON.stringify({spaces:spaces(),symbols:[],warnings:[],openings:[]})}]};}},{model:'claude-sonnet-5-5',inputUSDPerMillion:2,outputUSDPerMillion:10,maxOutputTokens:100,userRules:''});await ai({phase:'inventory',raster:raster(),previous:null,segmentation:null,maxUSD:.1});const task=body.messages[0].content.filter(c=>c.type==='text').map(c=>c.text).join(' ');assert.match(task,/nearStart/);assert.match(task,/not the arrow endpoints/);assert.match(task,/window alone does not/);});
test('opening validation and raster preview use the same non-default ink threshold',()=>{const f=recoveryFixture();f.r.gray=f.r.gray.map(v=>v===0?210:v);const cfg={...f.cfg,threshold:220},out=OpeningRecovery.recoverOpenings(f.r,f.s,[],cfg,[f.hint]);assert.equal(out.applied.length,1);assert.equal(out.segmentation.regions.length,1);});
const Focus=require('../dist/agency-plans/review-focus');
test('review magnification derives bounded crops from observations and maps every pixel exactly',()=>{const f=recoveryFixture(),original=Buffer.from(f.r.gray),previous={spaces:f.s,symbols:[],warnings:[],openings:[f.hint]},out=Focus.reviewFocus(f.r,previous,null);assert.equal(out.length,1);assert.deepEqual(out[0].origin,[0,0]);assert.equal(out[0].scale,3);assert.equal(out[0].raster.gray[45*out[0].raster.width+102],f.r.gray[15*80+34]);assert.deepEqual(Buffer.from(f.r.gray),original);assert.ok(out[0].raster.width<=840);});
test('review crops do not use unavailable observations or invent a target count',()=>{const f=recoveryFixture();assert.deepEqual(Focus.reviewFocus(f.r,null,null),[]);assert.deepEqual(Focus.reviewFocus(f.r,{spaces:[],symbols:[],warnings:[],openings:[{...f.hint,nearStart:[-200,-200],nearEnd:[-190,-190]}]},null),[]);});
test('compact diagnostics retain issues and seeds while omitting contour vertices',()=>{const f=recoveryFixture(),s=R.segmentPlan(f.r,f.s,[],f.cfg),compact=Focus.reviewDiagnostics(s);assert.deepEqual(compact.issues,s.issues);assert.equal(JSON.stringify(compact).includes('points'),false);assert.equal(Focus.reviewDiagnostics(null),null);});
test('a misplaced AI hint recovers unique nearby jambs across a thin arrow stroke without changing other rooms',()=>{const f=recoveryFixture();for(let x=60;x<=75;x++){f.r.gray[2*80+x]=0;f.r.gray[11*80+x]=0;}for(let y=2;y<=11;y++){f.r.gray[y*80+60]=0;f.r.gray[y*80+75]=0;}f.r.gray[15*80+40]=0;f.s.push({id:'other',kind:'room',label:'Other room',seeds:[[65,5]]});const h={...f.hint,nearStart:[25,15],nearEnd:[37,15]},before=R.segmentPlan(f.r,f.s,[],f.cfg),bytes=Buffer.from(f.r.gray),out=OpeningRecovery.recoverOpenings(f.r,f.s,[],f.cfg,[h]);assert.equal(out.applied.length,1);assert.equal(out.reviews[0].endpointSource,'pixel_neighborhood_search');assert.ok(out.reviews[0].search.tested>0);assert.deepEqual(out.segmentation.regions.find(v=>v.id==='other').points,before.regions.find(v=>v.id==='other').points);assert.deepEqual(Buffer.from(f.r.gray),bytes);assert.equal(out.confirmed,false);});
test('bridging annotations still refuses a solid wall and preserves the raw raster',()=>{const f=recoveryFixture(),before=Buffer.from(f.r.gray);const out=Recognition.detectOpeningGaps(f.r,{x:10,y:10,width:60,height:60},{bridgeAnnotations:true});assert.ok(out.every(v=>Recognition.proposeThresholds(f.r,[v])[0].canPreview));assert.deepEqual(Buffer.from(f.r.gray),before);});
const Arcs=require('../dist/agency-plans/door-arcs'),ServiceSurfaces=require('../dist/agency-plans/service-surfaces');
test('quarter-circle and hinge evidence propose a door repair without changing structural holes or input',()=>{const room=inwardDoorRoom(),before=structuredClone(room),out=Arcs.detectInwardDoorArcs(room,0);assert.ok(out.length>=1);assert.equal(out[0].source,'wall_detector');assert.deepEqual(out[0].geometry.holes,room.holes);assert.ok(G.polygonArea(out[0].geometry)>G.polygonArea(room));assert.deepEqual(room,before);});
test('a rectangular recess without circular evidence is not filled as a door',()=>{const room={id:'plain',label:'Plain',points:[[0,0],[60,0],[60,50],[35,50],[35,40],[25,40],[25,50],[0,50]],holes:[]};assert.deepEqual(Arcs.detectInwardDoorArcs(room,0),[]);});
test('service selection favors complete equally-supported envelopes, retains adjacent cells and excludes another room',()=>{const make=(id,x,y,w,h,support=[1,1,1,1])=>({id,label:id,geometry:rect(x,y,w,h),source:'wall_detector',state:'proposed',wallSupport:support,requiresInteriorReview:true});const candidates=[make('fixture-fragment',0,0,10,20),make('full',0,0,30,20),make('adjacent',0,25,30,20),make('weak-overshoot',0,0,35,20,[1,.6,1,1]),make('other-room',35,25,30,20)],s=[{id:'bath',kind:'bathroom',label:'Service',seeds:[[5,5]]},{id:'room',kind:'room',label:'Other',seeds:[[40,30]]}];const out=ServiceSurfaces.selectServiceSurfaces(candidates,s,'bath');assert.equal(out.length,2);assert.equal(G.polygonArea(out[0].geometry),600);assert.equal(out[0].id,'bath');assert.equal(out[1].id,'bath-cell-2');assert.ok(out.every(e=>e.requiresInteriorReview));});
